"use client";

import { useState, useEffect, useCallback, useRef } from "react";

const API_BASE = "http://localhost:4000";

interface GameData {
  status: string;
  currentQuestion: {
    id: number;
    type: string;
    difficulty: string;
    question: string;
    options: string[];
    timeLimit: number;
  } | null;
  currentQuestionIndex: number;
  totalQuestions: number;
  timeRemaining: number;
  leaderboard: {
    rank: number;
    username: string;
    displayName: string;
    points: number;
    streak: number;
    team: string | null;
    title: string;
  }[];
  correctAnswer: string | null;
  winner: string | null;
  winnerDisplayName: string | null;
  bossRound: boolean;
  questionsAsked: number;
  totalPlayers: number;
  stats: {
    totalPlayers: number;
    questionsAnswered: number;
    totalAnswers: number;
    correctAnswers: number;
    fastestAnswer: number | null;
    fastestPlayer: string | null;
    mostActivePlayer: string | null;
    sessionDuration: number;
  };
  sessionId: number | null;
}

type TabType = "control" | "leaderboard" | "stats" | "tiktok" | "simulate";

export default function AdminPage() {
  const [game, setGame] = useState<GameData | null>(null);
  const [tab, setTab] = useState<TabType>("control");
  const [tiktokUsername, setTiktokUsername] = useState("");
  const [tiktokConnected, setTiktokConnected] = useState(false);
  const [questionCount, setQuestionCount] = useState(20);
  const [difficulty, setDifficulty] = useState("mixed");
  const [simUsername, setSimUsername] = useState("");
  const [simMessage, setSimMessage] = useState("");
  const [events, setEvents] = useState<
    { type: string; data: string; time: string }[]
  >([]);
  const [addPointsUser, setAddPointsUser] = useState("");
  const [addPointsAmount, setAddPointsAmount] = useState(10);

  const pollRef = useRef<ReturnType<typeof setInterval>>(null);

  const fetchGame = useCallback(async () => {
    try {
      const res = await fetch(`${API_BASE}/game`);
      const data = await res.json();
      setGame(data);
    } catch (err) {
      console.log(err);
    }
  }, []);

  useEffect(() => {
    fetchGame();
    pollRef.current = setInterval(fetchGame, 500);

    return () => {
      if (pollRef.current) clearInterval(pollRef.current);
    };
  }, [fetchGame]);

  const gameAction = async (action: string, extra: Record<string, unknown> = {}) => {
    try {
      const res = await fetch(`${API_BASE}/game`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ action, ...extra }),
      });

      const data = await res.json();
      addEvent(action, JSON.stringify(data));
      fetchGame();
    } catch (err) {
      console.log(err);
    }
  };

  const simulateAnswer = async () => {
    if (!simUsername || !simMessage) return;

    try {
      const res = await fetch(`${API_BASE}/game/answer`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          username: simUsername.toLowerCase().replace(/\s/g, "_"),
          displayName: simUsername,
          message: simMessage,
        }),
      });

      const data = await res.json();

      addEvent(
        "answer",
        `${simUsername}: "${simMessage}" → ${
          data.correct ? "✅ CORRECT" : "❌ Wrong"
        }`
      );

      setSimMessage("");
      fetchGame();
    } catch (err) {
      console.log(err);
    }
  };

  const connectTikTok = async () => {
    try {
      const res = await fetch(`${API_BASE}/tiktok`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          action: "connect",
          username: tiktokUsername,
        }),
      });

      const data = await res.json();
      setTiktokConnected(data.connected);
      addEvent("tiktok", `Connected to @${tiktokUsername}`);
    } catch (err) {
      console.log(err);
    }
  };

  const disconnectTikTok = async () => {
    try {
      await fetch(`${API_BASE}/tiktok`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ action: "disconnect" }),
      });

      setTiktokConnected(false);
      addEvent("tiktok", "Disconnected");
    } catch (err) {
      console.log(err);
    }
  };

  const addEvent = (type: string, data: string) => {
    setEvents((prev) => [
      { type, data, time: new Date().toLocaleTimeString() },
      ...prev.slice(0, 49),
    ]);
  };

  const exportResults = async (format: string) => {
    const res = await fetch(
      `${API_BASE}/game/export?format=${format}`
    );

    if (format === "csv") {
      const blob = await res.blob();
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = "anime-wiz-results.csv";
      a.click();
    } else {
      const data = await res.json();
      const blob = new Blob([JSON.stringify(data, null, 2)], {
        type: "application/json",
      });

      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = "anime-wiz-results.json";
      a.click();
    }
  };

  const formatDuration = (ms: number) => {
    const s = Math.floor(ms / 1000);
    const m = Math.floor(s / 60);
    const h = Math.floor(m / 60);
    return `${h}h ${m % 60}m ${s % 60}s`;
  };

  const diffBadge = (d: string) => {
    const colors: Record<string, string> = {
      easy: "bg-cyan-500/20 text-cyan-300 border-cyan-500/40",
      medium: "bg-yellow-500/20 text-yellow-300 border-yellow-500/40",
      hard: "bg-orange-500/20 text-orange-300 border-orange-500/40",
      legendary: "bg-red-500/20 text-red-300 border-red-500/40",
    };
    return colors[d] || "bg-gray-500/20 text-gray-300 border-gray-500/40";
  };

  return (
    <div className="anime-bg min-h-screen">
      <header className="glass-card neon-border-pink mx-4 mt-4 p-4 flex justify-between">
        <h1 className="text-2xl font-bold">ANIME WIZ LIVE ARENA</h1>
        <div className="text-sm text-gray-300">
          👥 {game?.totalPlayers || 0} players
        </div>
      </header>

      <main className="mx-4 mt-4">
        <h2 className="text-white text-lg">
          Status: {game?.status || "offline"}
        </h2>

        <div className="mt-4">
          <button
            onClick={() => gameAction("start", { questionCount, difficulty })}
            className="btn-neon btn-neon-green"
          >
            Start Game
          </button>

          <button
            onClick={() => gameAction("next_question")}
            className="btn-neon btn-neon-blue ml-2"
          >
            Next Question
          </button>

          <button
            onClick={() => gameAction("end")}
            className="btn-neon btn-neon-red ml-2"
          >
            End Game
          </button>
        </div>

        {game?.currentQuestion && (
          <div className="mt-6 text-white">
            <h3>{game.currentQuestion.question}</h3>
          </div>
        )}
      </main>
    </div>
  );
}